<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::startSession($config);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);exit('Session expired.');}
try{$db=Database::connection();$user=WorkflowHelpers::requireUser($db,$config);if(!Authorization::can($db,$user,'foi.create'))throw new InvalidArgumentException('Your account cannot submit FOI requests.');if(($_POST['privacy_ack']??'')!=='1')throw new InvalidArgumentException('Please acknowledge the privacy notice.');$subject=WorkflowHelpers::clean((string)($_POST['subject']??''),180);$records=WorkflowHelpers::clean((string)($_POST['requested_records']??''),5000);$purpose=WorkflowHelpers::clean((string)($_POST['purpose']??''),1000);if($subject===''||$records==='')throw new InvalidArgumentException('Complete the subject and records requested.');$p=$db->prepare('SELECT first_name,middle_name,last_name,suffix FROM user_profiles WHERE user_id=:uid');$p->execute(['uid'=>$user['user_id']]);$profile=$p->fetch(PDO::FETCH_ASSOC)?:[];$name=trim(($profile['first_name']??$user['username']).' '.($profile['middle_name']??'').' '.($profile['last_name']??'').' '.($profile['suffix']??''));$ref=WorkflowHelpers::reference('FOI');$db->beginTransaction();$q=$db->prepare("INSERT INTO foi_requests (reference_code,user_id,requester_name,requester_email,subject,requested_records,purpose,status) VALUES (:ref,:uid,:name,:email,:subject,:records,:purpose,'SUBMITTED')");$q->execute(['ref'=>$ref,'uid'=>$user['user_id'],'name'=>$name,'email'=>$user['email'],'subject'=>$subject,'records'=>$records,'purpose'=>$purpose]);$id=(int)$db->lastInsertId();$h=$db->prepare("INSERT INTO foi_status_history (foi_request_id,old_status,new_status,notes,changed_by_user_id) VALUES (:id,NULL,'SUBMITTED','Initial FOI request',:uid)");$h->execute(['id'=>$id,'uid'=>$user['user_id']]);AuditLogger::record($db,(int)$user['user_id'],'FOI_REQUEST_SUBMITTED','foi_request',$id,['reference_code'=>$ref]);$db->commit();header('Location: dashboard.php?submitted=1');exit;
}catch(InvalidArgumentException $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();http_response_code(422);$msg=$e->getMessage();}catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();error_log('FOI submit: '.$e->getMessage());http_response_code(503);$msg='Unable to submit the FOI request.';}
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('FOI request not submitted');?><main id="main-content" class="section"><div class="notice warning"><?= Security::e($msg??'Request failed.') ?></div><a class="action-secondary" href="foi.php">Return to FOI page</a></main><?php pageFooter();
